      "heading_8": "Services",
      "heading_9": "Support",
      "heading_10": "Legal",
      "paragraph_11": "Comprehensive care across a wide range of medical fields, delivered by board-certified experts.",
      "paragraph_12": "Routine check-ups, flu treatment, prescription refills, and general health advice for adults.",
      "paragraph_13": "Compassionate therapy and psychiatry for anxiety, depression, stress, and more.",
      "paragraph_14": "Specialized care for children of all ages, from newborns to teenagers.",
      "paragraph_15": "Expert diagnosis and treatment for skin, hair, and nail conditions via high-res video.",
      "paragraph_16": "Comprehensive reproductive and general health services tailored for women.",
