      "heading_5": "Services",
      "heading_6": "Support",
      "heading_7": "Legal",
      "paragraph_8": "Board-certified specialists dedicated to providing ethical, high-quality care.",
      "paragraph_9": "15+ years experience in internal medicine and preventative care.",
      "paragraph_10": "Specializing in anxiety disorders and cognitive behavioral therapy.",
      "paragraph_11": "Dedicated to providing compassionate care for children and adolescents.",
